//! Go bindings for libghostty-vt, generated by zigo.
const zigo = @import("zigo");
const gostty = @import("gostty");

pub const bindings = zigo.define(.{
    .root = gostty,
    .allocator = .smp_allocator,
    .io = "io",
    // Key and mouse encoding is over half the public surface -- the `Key` enum
    // alone is 176 constants -- and nothing on the terminal side names it, so it
    // gets its own package. The dependency runs one way: `input` names
    // `*Terminal`, the root package names nothing from `input`.
    .packages = .{
        .{
            .path = "input",
            .doc = "Package input encodes key, mouse, focus and paste events into the bytes a program reading the pty expects.",
            .types = .{
                "KeyEvent",
                "MouseEvent",
                "RenderSize",
                "Key",
                "KeyAction",
                "KeyMod",
                "FocusEvent",
                "MouseAction",
                "MouseButton",
            },
            .functions = .{
                "root.encodeKey",
                "root.encodeMouse",
                "root.encodeFocus",
                "root.isSafePaste",
                "root.encodePaste",
            },
        },
    },

    .types = .{
        .{ .type = gostty.Terminal, .repr = .@"opaque" },
        .{ .type = gostty.Stream, .repr = .@"opaque", .name = "Stream" },
        .{ .type = gostty.Screen, .repr = .@"opaque", .name = "Screen" },
        .{ .type = gostty.Search, .repr = .@"opaque", .name = "Search" },
        .{ .type = gostty.KeyEvent, .repr = .@"opaque", .name = "KeyEvent" },
        .{ .type = gostty.MouseEvent, .repr = .@"opaque", .name = "MouseEvent" },
        .{ .type = gostty.RenderSize, .repr = .value, .name = "RenderSize" },
        .{ .name = "CursorStyle", .type = gostty.CursorStyle, .repr = .enumeration },
        .{ .name = "CursorStyleReq", .type = gostty.CursorStyleReq, .repr = .enumeration },
        .{ .name = "EraseDisplay", .type = gostty.EraseDisplay, .repr = .enumeration },
        // ghostty leaves these two non-exhaustive so a number from a pty never
        // fails `@enumFromInt`; carry that through to Go rather than closing it.
        .{ .name = "EraseLine", .type = gostty.EraseLine, .repr = .enumeration, .exhaustive = false },
        .{ .name = "TabClear", .type = gostty.TabClear, .repr = .enumeration, .exhaustive = false },
        .{ .name = "ProtectedMode", .type = gostty.ProtectedMode, .repr = .enumeration },
        .{ .name = "ScreenKey", .type = gostty.ScreenKey, .repr = .enumeration },
        .{ .name = "Underline", .type = gostty.Underline, .repr = .enumeration },
        .{ .name = "ColorName", .type = gostty.ColorName, .repr = .enumeration, .exhaustive = false },
        .{ .name = "Attribute", .type = gostty.Attribute, .repr = .tagged_union },
        .{ .name = "SearchDirection", .type = gostty.SearchDirection, .repr = .enumeration },
        .{ .name = "Key", .type = gostty.Key, .repr = .enumeration },
        .{ .name = "KeyAction", .type = gostty.KeyAction, .repr = .enumeration },
        .{ .name = "KeyMod", .type = gostty.KeyMod, .repr = .enumeration },
        .{ .name = "FocusEvent", .type = gostty.FocusEvent, .repr = .enumeration },
        .{ .name = "MouseAction", .type = gostty.MouseAction, .repr = .enumeration },
        .{ .name = "MouseButton", .type = gostty.MouseButton, .repr = .enumeration },
        .{ .name = "Charset", .type = gostty.Charset, .repr = .enumeration },
        .{ .name = "CharsetSlot", .type = gostty.CharsetSlot, .repr = .enumeration },
        .{ .name = "CharsetActiveSlot", .type = gostty.CharsetActiveSlot, .repr = .enumeration },
        .{ .name = "DeccolmMode", .type = gostty.DeccolmMode, .repr = .enumeration },
        .{ .name = "ScrollViewport", .type = gostty.ScrollViewport, .repr = .tagged_union },
    },
    .functions = .{
        .{ .path = "root.unicode.codepointWidth" },
        .{ .path = "root.graphemeWidth", .params = .{"cps"} },

        // Input encoding.
        .{ .path = "root.newKeyEvent", .constructs = "KeyEvent" },
        .{ .path = "root.freeKeyEvent", .destroys = "KeyEvent" },
        .{ .path = "KeyEvent.reset" },
        .{ .path = "KeyEvent.setAction", .params = .{"action"} },
        .{ .path = "KeyEvent.setKey", .params = .{"key"} },
        .{ .path = "KeyEvent.setMod", .params = .{ "mod", "value" } },
        .{ .path = "KeyEvent.setConsumedMod", .params = .{ "mod", "value" } },
        .{ .path = "KeyEvent.setComposing", .params = .{"composing"} },
        .{ .path = "KeyEvent.setUtf8", .params = .{"text"} },
        .{ .path = "KeyEvent.setUnshiftedCodepoint", .params = .{"cp"} },
        .{ .path = "root.encodeKey", .params = .{ "writer", "terminal", "event" } },
        .{ .path = "root.newMouseEvent", .constructs = "MouseEvent" },
        .{ .path = "root.freeMouseEvent", .destroys = "MouseEvent" },
        .{ .path = "MouseEvent.reset" },
        .{ .path = "MouseEvent.setAction", .params = .{"action"} },
        .{ .path = "MouseEvent.setButton", .params = .{"button"} },
        .{ .path = "MouseEvent.clearButton" },
        .{ .path = "MouseEvent.setMod", .params = .{ "mod", "value" } },
        .{ .path = "MouseEvent.setPosition", .params = .{ "x", "y" } },
        .{ .path = "root.encodeMouse", .params = .{ "writer", "terminal", "event", "size", "any_button_pressed" } },
        .{ .path = "root.encodeFocus", .params = .{ "writer", "event" } },
        .{ .path = "root.isSafePaste", .params = .{"data"} },
        .{ .path = "root.encodePaste", .params = .{ "writer", "terminal", "data" } },

        // Lifecycle. `Terminal.init` returns by value and takes an `Options`
        // that cannot cross the C ABI, so the pair lives outside the type.
        .{ .path = "root.newTerminal", .constructs = "Terminal" },
        .{ .path = "root.freeTerminal", .destroys = "Terminal" },
        .{ .path = "root.freeString", .params = .{"str"} },
        // A stream borrows its terminal: ghostty's handler reaches through it for
        // an allocator when it tears down, so the terminal must outlive it.
        .{ .path = "root.newStream", .constructs = "Stream", .child_of_receiver = true, .params = .{"continuation_max_bytes"} },
        .{ .path = "root.freeStream", .destroys = "Stream" },
        .{ .path = "root.streamFailed", .name = "failed" },
        .{ .path = "Stream.nextSlice", .name = "feed", .params = .{"input"} },
        .{ .path = "Stream.writeContinuation", .params = .{"writer"} },

        // ghostty's own methods, bound directly.
        .{ .path = "Terminal.printString", .params = .{"str"} },
        .{ .path = "Terminal.plainString", .returns = .caller, .release = "root.freeString" },
        .{ .path = "Terminal.setCursorStyle", .params = .{"value"} },
        .{ .path = "Terminal.setCursorPos", .params = .{ "row_req", "col_req" } },
        .{ .path = "Terminal.carriageReturn" },
        .{ .path = "Terminal.linefeed" },
        .{ .path = "Terminal.backspace" },
        .{ .path = "Terminal.cursorIsAtPrompt" },
        .{ .path = "Terminal.fullReset" },
        .{ .path = "root.switchScreen", .params = .{"key"} },
        .{ .path = "root.activeScreenKey" },
        .{ .path = "root.activeScreen", .returns = .borrowed },
        .{ .path = "root.screen", .returns = .borrowed, .params = .{"key"} },
        .{ .path = "root.screenSelectAll", .name = "selectAll" },
        .{ .path = "root.screenClearSelection", .name = "clearSelection" },
        .{ .path = "root.screenHasSelection", .name = "hasSelection" },
        .{ .path = "root.newSearch", .constructs = "Search", .child_of_receiver = true, .params = .{"needle"} },
        .{ .path = "root.freeSearch", .destroys = "Search" },
        .{ .path = "Search.searchAll" },
        .{ .path = "root.searchMatchCount", .name = "matchCount" },
        .{ .path = "root.searchSelect", .name = "select", .params = .{"to"} },
        .{ .path = "root.screenSelectionString", .name = "selectionString", .returns = .caller, .release = "root.freeString" },
        .{
            .path = "root.printAttributesInto",
            .params = .{"dst"},
            .param_meta = .{ .dst = .{ .direction = .out, .written = .@"return" } },
        },
        .{ .path = "root.historyString", .returns = .caller, .release = "root.freeString" },
        .{ .path = "root.screenString", .returns = .caller, .release = "root.freeString" },

        // Cursor movement.
        .{ .path = "Terminal.cursorUp", .params = .{"count_req"} },
        .{ .path = "Terminal.cursorDown", .params = .{"count_req"} },
        .{ .path = "Terminal.cursorLeft", .params = .{"count_req"} },
        .{ .path = "Terminal.cursorRight", .params = .{"count_req"} },
        .{ .path = "Terminal.saveCursor" },
        .{ .path = "Terminal.restoreCursor" },
        .{ .path = "Terminal.index" },
        .{ .path = "Terminal.reverseIndex" },

        // Tab stops.
        .{ .path = "Terminal.horizontalTab" },
        .{ .path = "Terminal.horizontalTabBack" },
        .{ .path = "Terminal.tabSet" },
        .{ .path = "Terminal.tabReset" },
        .{ .path = "Terminal.tabClear", .params = .{"cmd"} },

        // Scrolling and margins.
        .{ .path = "Terminal.scrollUp", .params = .{"count"} },
        .{ .path = "Terminal.scrollDown", .params = .{"count"} },
        .{ .path = "Terminal.setTopAndBottomMargin", .params = .{ "top_req", "bottom_req" } },
        .{ .path = "Terminal.setLeftAndRightMargin", .params = .{ "left_req", "right_req" } },
        .{ .path = "Terminal.setScrollbackMaxBytes", .params = .{"max"} },
        .{ .path = "Terminal.setScrollbackMaxLines", .params = .{"max"} },

        // Editing.
        .{ .path = "Terminal.insertLines", .params = .{"count"} },
        .{ .path = "Terminal.deleteLines", .params = .{"count"} },
        .{ .path = "Terminal.insertBlanks", .params = .{"count"} },
        .{ .path = "Terminal.deleteChars", .params = .{"count_req"} },
        .{ .path = "Terminal.eraseChars", .params = .{"count_req"} },
        .{ .path = "Terminal.eraseLine", .params = .{ "mode", "protected_req" } },
        .{ .path = "Terminal.eraseDisplay", .params = .{ "mode", "protected_req" } },
        .{ .path = "Terminal.decaln" },

        // Printing.
        .{ .path = "Terminal.print", .params = .{"c"} },
        .{ .path = "Terminal.printRepeat", .params = .{"count_req"} },
        .{ .path = "Terminal.printSlice", .params = .{"cps"} },
        .{ .path = "Terminal.plainStringUnwrapped", .returns = .caller, .release = "root.freeString" },

        // Metadata the terminal tracks for the shell.
        .{ .path = "Terminal.setPwd", .params = .{"pwd"} },
        .{ .path = "Terminal.getPwd" },
        .{ .path = "Terminal.getTitle" },
        .{ .path = "Terminal.setTitle", .params = .{"t"} },
        .{ .path = "root.setAttribute", .params = .{"attr"} },
        .{ .path = "Terminal.setProtectedMode", .params = .{"mode"} },
        .{ .path = "Terminal.setDefaultCursorStyle", .params = .{"configured_style"} },
        .{ .path = "Terminal.setDefaultCursorBlink", .params = .{"blink"} },
        .{ .path = "Terminal.configureCharset", .params = .{ "slot", "set" } },
        .{ .path = "Terminal.invokeCharset", .params = .{ "active", "slot", "single" } },
        .{ .path = "Terminal.deccolm", .params = .{"mode"} },
        .{ .path = "Terminal.scrollViewport", .params = .{"behavior"} },
        .{ .path = "Terminal.compressionActivity" },
        .{ .path = "root.resize", .params = .{ "width", "height" } },

        // Field accessors: zigo binds functions, not fields.
        .{ .path = "root.cols" },
        .{ .path = "root.rows" },
        .{ .path = "root.cursorX" },
        .{ .path = "root.cursorY" },
        .{ .path = "root.cursorStyle" },
    },
});
